int git_pkt_parse_ref(out git_pkt **pkt, const char *line, size_t len) {
    git_pkt_ng *ng_pkt = malloc(sizeof(git_pkt_ng));
    if (!ng_pkt) {
        return -1;
    }

    // Clear structure
    memset(ng_pkt, 0, sizeof(git_pkt_ng));

    // Validate input line format
    if (len < 4 || memcmp(line, "ref ", 4) != 0) {
        free(ng_pkt);
        return -1;
    }

    // Skip "ref " prefix
    line += 4;
    len -= 4;

    // Find space between reference and message
    const char *space = memchr(line, ' ', len);
    if (!space) {
        free(ng_pkt);
        return -1;
    }

    // Calculate lengths
    size_t ref_len = (size_t)(space - line);
    size_t msg_len = len - ref_len - 1; // minus space

    // Allocate memory for reference and message
    ng_pkt->ref = malloc(ref_len + 1);
    ng_pkt->msg = malloc(msg_len + 1);

    if (!ng_pkt->ref || !ng_pkt->msg) {
        free(ng_pkt->ref);
        free(ng_pkt->msg);
        free(ng_pkt);
        return -1;
    }

    // Copy reference and message
    memcpy(ng_pkt->ref, line, ref_len);
    ng_pkt->ref[ref_len] = '\0';
    line = space + 1;
    memcpy(ng_pkt->msg, line, msg_len);
    ng_pkt->msg[msg_len] = '\0';

    *pkt = (git_pkt *)ng_pkt;
    return 0;
}

int git_pkt_parse_ref(out git_pkt **pkt, const char *line, size_t len)
{
    git_pkt *p;
    char *space, *nl, *buf;
    size_t pkt_len;

    if (len < 5)
        return -1;

    pkt_len = len - 4;
    if (pkt_len > strlen(line))
        return -1;

    p = malloc(sizeof(*p));
    if (!p)
        return -1;

    buf = strdup(line);
    if (!buf) {
        free(p);
        return -1;
    }

    space = strchr(buf, ' ');
    if (!space) {
        free(buf);
        free(p);
        return -1;
    }

    *space = '\0';
    p->ref = strdup(buf);
    if (!p->ref) {
        free(buf);
        free(p);
        return -1;
    }

    nl = strchr(space + 1, '\n');
    if (nl)
        *nl = '\0';

    p->msg = strdup(space + 1);
    if (!p->msg) {
        free(p->ref);
        free(p);
        free(buf);
        return -1;
    }

    *pkt = p;
    return 0;
}

