int git_pkt_parse_ref(out git_pkt **pkt, const char *line, size_t len) {
    git_pkt_ng *p;
    const char *ref, *msg;
    size_t ref_len, msg_len;

    if (len < 5 || memcmp(line, "ref ", 4) != 0) {
        return -1;
    }

    p = malloc(sizeof(*p));
    if (!p) {
        return -1;
    }

    ref = line + 4;
    ref_len = strcspn(ref, " ");
    if (ref_len == 0) {
        free(p);
        return -1;
    }

    msg = ref + ref_len + 1;
    msg_len = len - (msg - line);

    p->type = PKT_REF;
    p->ref = strndup(ref, ref_len);
    if (!p->ref) {
        free(p);
        return -1;
    }

    if (msg_len > 0) {
        p->msg = strndup(msg, msg_len);
        if (!p->msg) {
            free(p->ref);
            free(p);
            return -1;
        }
    } else {
        p->msg = NULL;
    }

    *pkt = (git_pkt **)&p;
    return 0;
}

